import numpy as np

def relu(x):
    return np.maximum(0, x)

def leaky_relu(x, alpha=0.01):
    return np.where(x > 0, x, alpha * x)

def elu(x, alpha=1.0):
    return np.where(x > 0, x, alpha * (np.exp(x) - 1))

test_inputs = np.array([-5.0, -2.0, -1.0, -0.5, 0.5])

print("Input | ReLU | Leaky ReLU | ELU")
for x in test_inputs:
    relu_out = relu(x)
    leaky_out = leaky_relu(x)
    elu_out = elu(x)
    print(f"  {x:5.1f} | {relu_out:5.2f} |   {leaky_out:7.4f}  | {elu_out:.4f}")

print("\nNotice ReLU is always exactly 0 for negative inputs, Leaky ReLU keeps growing linearly (more negative),")
print("while ELU smoothly saturates, never going much below -1")
